"""Inspect the workspace: list files and summarize any SQLite databases."""

import os
import sqlite3


def main() -> None:
    for name in sorted(os.listdir(".")):
        if os.path.isfile(name):
            print(f"FILE: {name}")
        elif os.path.isdir(name):
            print(f"DIR:  {name}/")

    print("\n--- SQLite databases ---")
    for name in sorted(os.listdir(".")):
        if not (os.path.isfile(name) and name.endswith((".db", ".sqlite", ".sqlite3"))):
            continue
        print(f"\nDB: {name}")
        try:
            with sqlite3.connect(name) as conn:
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                if not tables:
                    print("  (no tables)")
                for (table,) in tables:
                    print(f"  table: {table}")
                    for row in cur.execute(f"PRAGMA table_info({table!r})"):
                        # PRAGMA table_info does not accept bound parameters.
                        print(f"    col: {row[1]}  type: {row[2]}  notnull: {row[3]}  default: {row[4]}")
        except sqlite3.Error as exc:
            print(f"  could not open: {exc}")


if __name__ == "__main__":
    main()

"""Inspect indexes/constraints on the users table of user_credentials.db."""

import sqlite3

DB_PATH = "user_credentials.db"


def main() -> None:
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.cursor()
        print("Indexes:")
        for row in cur.execute("PRAGMA index_list('users')"):
            print(" ", row)
        print("Index details:")
        for (index_name,) in cur.execute(
            "SELECT name FROM sqlite_master WHERE type='index' AND tbl_name='users'"
        ):
            for row in cur.execute(f"PRAGMA index_info({index_name!r})"):
                print(f"  {index_name}: {row}")
        print("Sample rows (first 5):")
        for row in cur.execute("SELECT id, username, email, created_date, access_rights FROM users LIMIT 5"):
            print(" ", row)


if __name__ == "__main__":
    main()

